// Try to submit empty form
cy.get('button[type="submit"], input[type="submit"]')
    .first()
    .click({ force: true });
// Should show validation errors or prevent submission
cy.wait(500);

cy.get("form")
    .first()
    .within(function () {
    // Fill name field
    cy.get('input[name*="name" i], input[placeholder*="name" i]')
        .first()
        .type("John Doe", { force: true });
    // Fill email field
    cy.get('input[type="email"], input[name*="email" i], input[placeholder*="email" i]')
        .first()
        .type("john.doe@example.com", { force: true });
    // Fill phone field
    cy.get('input[type="tel"], input[name*="phone" i], input[placeholder*="phone" i]')
        .first()
        .type("4691234567", { force: true });
    // Fill message/comment field
    cy.get('textarea, input[name*="message" i], input[name*="comment" i]')
        .first()
        .type("This is a test message for Cypress automation.", {
        force: true,
    });
    cy.wait(500);
    // Submit form
    cy.get('button[type="submit"], input[type="submit"]')
        .first()
        .click({ force: true });
    cy.wait(2000);
});
// Check for success message or confirmation
cy.get("body").then(function ($body) {
    var bodyText = $body.text().toLowerCase();
    var successIndicators = [
        "success",
        "thank",
        "submitted",
        "received",
        "sent",
    ];
    var hasSuccess = successIndicators.some(function (indicator) {
        return bodyText.includes(indicator);
    });
    cy.log(hasSuccess
        ? "✓ Form submitted successfully"
        : "Form submission completed");
});

cy.get('input[type="email"], input[name*="email" i]')
    .first()
    .type("invalid-email", { force: true })
    .blur();
// HTML5 validation should trigger
cy.get('input[type="email"]')
    .first()
    .then(function ($input) {
    expect($input[0].validationMessage).to.not.be.empty;
});

